import { NODE_TYPE } from "../components/flow-components/qa-tree-node-list-config";
import { v4 as uuidv4 } from "uuid";

export const convertEdgeToGraphEdge = ({
  EdgeID,
  Source,
  Target,
  SourceAnchor,
  TargetAnchor,
  Label,
}) => {
  return {
    id: EdgeID,
    source: Source,
    target: Target,
    sourceAnchor: SourceAnchor,
    targetAnchor: TargetAnchor,
    label: Label,
  };
};

export const convertNodeToGraphNode = (node) => {
  const { NodeID, NodeType, NodeName, NodeUI: { X, Y } = {} } = node;
  return {
    id: NodeID,
    type: NodeType === NODE_TYPE.START.type ? "start-node" : "custom-node",
    x: +X,
    y: +Y,
    nodeData: {
      // TODO: 存储数据
      data: {
        foo: 1,
      },
      NodeName,
      NodeType,
    },
  };
};

/**
 * 生成UUID
 * @returns {string} UUID，形式如 xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx，其中x的范围为0~9a-f
 */
export const getUUID = () => {
  return uuidv4();
};
