<template>
  <div class="nodes-preview">
    <div class="caption">执行节点，拖拽放置图中</div>
    <!-- {{ nodesList }} -->
    <div class="node-container">
      <div
        v-for="(nodesConfig, index) of nodesList"
        :key="index"
        class="node-list"
      >
        <div class="title">
          {{ nodesConfig[0] }}
        </div>
        <node
          v-for="(node, index2) in nodesConfig[1]"
          :key="index2"
          :node="node"
        />
      </div>
    </div>
  </div>
</template>

<script>
import Node from "./node.vue";
import { NODE_TYPE_LIST } from "../../qa-tree-node-list-config";
import _ from "lodash";

export default {
  name: "NodesPreview",
  components: {
    Node,
  },
  props: {},

  data() {
    return {
      slotNodeList: NODE_TYPE_LIST,
    };
  },
  computed: {
    nodesList() {
      return _.entries(_.groupBy(this.slotNodeList, (v) => v.group));
    },
  },
  methods: {},
};
</script>

