import { getUUID } from "@/utils";
import { NODE_TYPE_LIST } from "../qa-tree-node-list-config";

const NODE_TYPE_MAPS = {
  START: "start-node",
};

export default {
  getEvents() {
    return {
      "canvas:drop": "onCanvasDrop",
    };
  },
  onCanvasDrop({ clientX, clientY, originalEvent }) {
    if (!originalEvent.dataTransfer) return; // 不是拖动新建

    const nodeType = originalEvent.dataTransfer.getData("text/plain");
    const nodeOpt = NODE_TYPE_LIST.find((node) => node.type === nodeType);

    if (!nodeOpt) return;
    const point = this.graph.getPointByClient(clientX, clientY);
    console.log(nodeOpt);
    // 同类数量
    const num = this.graph.nodeNum[nodeType];
    const node = this.graph.addItem("node", {
      id: "node-" + getUUID(),
      type: NODE_TYPE_MAPS[nodeType] || "custom-node",
      x: point.x,
      y: point.y,
      nodeData: {
        NodeName: `${nodeOpt.name}${num + 1}`,
        NodeType: nodeType,
      },
    });
    // 更新数量
    this.graph.nodeNum[nodeType] += 1;

    // 弹出设置面板
    this.graph.emit("clickNode", { item: node, isNewNode: true });
  },
};
