/* eslint-disable @typescript-eslint/no-this-alias */
import { NODE_TYPE } from "../qa-tree-node-list-config";
import { getUUID } from "@/utils";

export default {
  getEvents() {
    return {
      // "node:dragstart": "onDragStart",
      dragstart: "onDragStart",
      "node:dragleave": "onDragLeave",
      drag: "updateEndPoint",
      "node:drop": "onDragStart",
      dragend: "onDragEnd",
    };
  },
  calcShouldBegin(ev) {
    const { target, item } = ev;
    const targetName = target.get("name") || "";
    if (
      targetName === "source-hot-area" &&
      !this.graph._addingEdge &&
      !this.graph._addingEdge1
    ) {
      return true;
    }
  },
  // 可以结束 edge
  calcShouldEnd({ item }) {
    console.log("==========");
    const itemType = item?.getType() ?? "";
    if (itemType === "node" && this.edge) {
      const currentNode = item;
      const currentNodeModel = currentNode.getModel();
      // 终点不可以是开始节点, 不可以是自己
      // DESC: 结束点不可以是开始点
      if (currentNodeModel.type === "start-node") {
        console.log("TIP: 结束不可以是 start-node");
        return false;
      }

      // DESC: 结束点不可以是自己
      const currentSource = this.edge.getSource();
      if (currentSource === currentNode) {
        console.log("TIP: 结束不可以是自己");
        return false;
      }

      // DESC: 起始点不能有多个 edge ,由后续创建完后的 验证环节去掉
      // if (currentSource.getModel().type === "start-node") {
      //   if (currentSource.getEdges().length > 1) {
      //     return false;
      //   }
      // }

      const currentSourceEdges = currentSource.getEdges();
      // TODO: 根据类型判断反方向连线
      const existing = currentSourceEdges.find((edge) => {
        if (edge === this.edge) {
          //此 edge 是当前 edge
          return false;
        }
        const target = edge.getTarget();
        const source = edge.getSource();
        if (target === currentNode) {
          return true;
        }
        if (source === currentNode) {
          return true;
        }
      });
      // if (existing) {
      //   return false;
      // }
      return true;
    }
    return false;
  },
  onDragLeave(ev) {},
  onDragEnd(ev) {
    console.log("=====onDragEnd", ev.item, this.edge);
    this.drawEdgeEnd({ item: this.edge });
  },
  drawEdgeEnd(ev) {
    if (this.key && !this.keydown) return;
    // 如果起点已经指定而终点未指定，则指定终点
    if (this.edge && this.calcShouldEnd(ev)) {
      const getEdgeConfig = this.getEdgeConfig;
      const node = ev.item;
      const model = node.getModel();
      let edgeConfig;
      if (getEdgeConfig) {
        edgeConfig = getEdgeConfig(
          {
            source: this.source,
            target: model.id,
          },
          this
        );
      } else {
        edgeConfig = this.edgeConfig;
      }

      const updateCfg = {
        target: model.id,
        ...edgeConfig,
        sourceAnchor: model.id === NODE_TYPE.START.id ? 0 : 1,
        targetAnchor: 0,
      };

      // 更新边
      this.updateEdge(updateCfg);
    } else {
      // 无法创建 edge ，删除 edge， 结束创建流程
      this.cancelCreate();
      this.createEnd();
    }
  },
  onDragStart(ev) {
    if (this.key && !this.keydown) return;
    const node = ev.item;

    if (this.calcShouldBegin(ev)) {
      const graph = this.graph;
      const getEdgeConfig = this.getEdgeConfig;
      const model = node.getModel();
      // 获取自定义 edge 配置
      let edgeConfig;
      if (getEdgeConfig) {
        edgeConfig = getEdgeConfig(
          {
            source: model.id,
            target: model.id,
          },
          this
        );
      } else {
        edgeConfig = this.edgeConfig;
      }

      this.edge = graph.addItem(
        "edge",
        {
          id: "node-" + getUUID(),
          source: model.id,
          target: model.id,
          ...edgeConfig,
          label: "edge 2",
        },
        false
      );
      this.graph.setItemState(this.edge, "updating", true);
      this.source = model.id;
      this.startCreate();
      // 将该边的 capture 设置为 false，这样可以拾取到后面的元素
      this.edge.getKeyShape().set("capture", false);
    } else {
      this.drawEdgeEnd(ev);
    }
  },
  updateEdge(updateCfg) {
    const graph = this.graph;

    graph.updateItem(this.edge, updateCfg, false);
    if (graph.get("enabledStack")) {
      const addedModel = {
        ...this.edge.getModel(),
        itemType: "edge",
      };
      const after = {};
      after.edges = [addedModel];
      graph.pushStack("add", {
        before: {},
        after,
      });
    }

    graph.emit("afterUpdateEdge", {
      item: this.edge,
    });

    this.createEnd();
  },
  cancelCreate() {
    if (this.edge && !this.edge.destroyed) {
      this.graph.removeItem(this.edge, false);
    }
  },
  createEnd() {
    if (this.edge) {
      // FIX: 可能存在其他地方被删除的情况，执行 stopCreate。此时会设置不了 state.
      if (!this.edge.destroyed) {
        this.edge.getKeyShape().set("capture", true);
        this.graph.setItemState(this.edge, "updating", false);
      }
      this.edge = null;
      this.stopDialog();
      const edgeGroup = this.graph.get("edgeGroup");
      if (edgeGroup) {
        edgeGroup.toBack();
        edgeGroup.set("capture", true);
        this.graph.paint();
      }
    }
    setTimeout(() => {
      this.graph._addingEdge = false;
    }, 0);
  },
  startDialog() {
    this.graph._isInDialog = true;
  },
  stopDialog() {
    this.graph._isInDialog = false;
  },
  startCreate() {
    const edgeGroup = this.graph.get("edgeGroup");
    if (edgeGroup) {
      edgeGroup.toFront();
      this.graph.paint();
    }
    this.graph._addingEdge = true;
  },
  // 边的起点已经确定，边的末端跟随鼠标移动
  updateEndPoint(ev) {
    if (this.key && !this.keydown) return;
    if (this.edge && this.edge.destroyed) {
      this.cancelCreating({ item: this.edge });
    }
    const point = { x: ev.x, y: ev.y };

    // 若此时 source 节点已经被移除，结束添加边
    if (!this.graph.findById(this.source)) {
      this.createEnd();
      return;
    }
    if (this.edge) {
      // 更新边的终点为鼠标位置
      this.graph.updateItem(
        this.edge,
        {
          target: point,
        },
        false
      );
    }
  },
  // 取消增加边，删除该边；
  cancelCreating(ev) {
    if (this.key && !this.keydown) return;
    const graph = this.graph;
    const currentEdge = ev.item;
    if (
      this.edge === currentEdge ||
      (ev.target && ev.target.isCanvas && ev.target.isCanvas())
    ) {
      if (this.edge && !this.edge.destroyed) graph.removeItem(this.edge, false);
      this.createEnd();
    }
  },
};
