export default {
  getEvents() {
    return {
      "edge:mouseenter": "onEdgeMouseEnter",
      "edge:mouseleave": "onEdgeMouseLeave",
      "edge:click": "onEdgeClick",
      afterupdateitem: "onEdgeUpdated",
    };
  },
  onEdgeClick(ev) {
    const target = ev.target;
    const targetType = target.get("name");
    if (targetType === "edgeButton:delete") {
      // 执行删除 edge 动作
      const group = target.getParent();
      this.graph.removeItem(group.get("item"));
    }
  },
  onEdgeUpdated() {
    // console.log("onEdgeUpdated");
  },
  xonEdgeMouseEnter(e) {},
  // TODO: 只创建一个 button 并且添加hover 变大变小动画
  onEdgeMouseLeave(e) {
    const { item } = e;
    const group = item.getContainer();
    const deleteButtons = group.find((v) => {
      const vName = v.get("name");
      return vName === "edgeButton:delete";
    });
    if (deleteButtons) {
      [deleteButtons].forEach((button) => {
        console.log(button);
        if (!deleteButtons.destroyed) {
          group.removeChild(button);
        }
      });
    }
    console.log("deleteButtons", deleteButtons);
  },
  xonEdgeMouseLeave(e) {
    const { item } = e;
    const group = item.getContainer();
    const deleteButton = group.find((v) => {
      const vName = v.get("name");
      return vName === "edgeButton:delete";
    });
    if (deleteButton) {
      deleteButton.attr({
        fill: "#ff9900",
        r: 0,
      });
    }
    console.log("deleteButtons", deleteButton);
  },
  // 还是每次重新生成吧，这样位置是准确的
  onEdgeMouseEnter(e) {
    console.log("onEdgeMouseEnter");
    const { item } = e;
    const group = item.getContainer();
    console.log("=============");
    console.log("=============");
    // let deleteButton = group.find(function (item) {
    //   return item.get("name") === "edgeButton:delete";
    // });

    group
      .addShape("circle", {
        attrs: {
          r: 10,
          fill: "rgba(123,11,234,0.3)",
          stroke: "#000",
          lineWidth: 2,
          opacity: 1,
          ...item.getKeyShape().getPoint(0.2),
        },
        capture: true,
        zIndex: 10000,
        name: "edgeButton:delete",
      })
      .animate(
        {
          opacity: 1,
        },
        300
      );

    group.sort();
  },
};
