import G6 from "@antv/g6";
import _ from "lodash";

const lineDash = [40, 20, 10, 20];
const deratLength = _.sum(lineDash);

// FLOW-DOC: 自定义 cubic-vertical 进行扩展
// 必须是实例方法，否则不会调用

export const tCubicVertical = {
  // 连线绘制完成时，实际上，触发时机在开始画的时候
  afterDraw(cfg, group) {},

  setState(name, value, item) {
    const baseEdgeType = item.get("currentShape").match(/custom:(.+)/)[1];
    if (baseEdgeType) {
      G6.Shape.Edge.getShape(baseEdgeType).setState(name, value, item);
    }

    const group = item.getContainer();
    const shape = item.getKeyShape?.() || group["shapeMap"]["edge-shape"];

    // 监听 running 状态
    if (name === "running") {
      // running 状态为 true 时
      if (value) {
        let index = 0;
        // 边 path 图形的动画
        shape.animate(
          () => {
            // DESC: 动画速度， 每一帧的动画长度
            index = index + 0.4;
            if (index > deratLength) {
              index = 0;
            }
            const res = {
              lineDash,
              lineDashOffset: -index,
            };
            // 返回需要修改的参数集，这里修改了 lineDash,lineDashOffset
            return res;
          },
          {
            repeat: true, // 动画重复
            duration: 30, // 一次动画的时长为 3000
          }
        );
      } else {
        // running 状态为 false 时
        // 结束动画
        shape.stopAnimate();
        // 清空 lineDash
        shape.attr("lineDash", null);
      }
    }

    // 鼠标 hover 时候 active
    if (name === "active") {
      // shape.attr(activeStyle);
    }

    if (name === "updating") {
      if (value) {
        const updatingStyle = item.get("styles").updating;
        shape.attr(updatingStyle);
      } else {
        const baseStyle = item.getModel().style;
        console.log(baseStyle, "1====1");
        shape.attr(baseStyle);
      }
    }
  },
};
