import startNodeIcon from "@/assets/icons/start-node.svg";
import deleteIcon from "@/assets/icons/delete-icon.svg";
import { NODE_TYPE } from "../qa-tree-node-list-config";
import addIcon from "@/assets/icons/copy-icon.svg";
import copyIcon from "@/assets/icons/copy-icon.svg";
import infoNodeIcon from "@/assets/icons/info-node.svg";
import apiNodeIcon from "@/assets/icons/api-node.svg";
import completeNodeIcon from "@/assets/icons/complete-node.svg";
import errorIcon from "@/assets/icons/error-icon.svg";

class StartNode {
  buttonStyle = {
    width: 20,
    height: 20,
    radius: 3,
    cursor: "pointer",
    // FLOW-DOC:: hover 按钮的间距
    // gap: 4,
    gap: 0,
  };

  iconStyle = {
    width: 28,
    height: 28,
  };

  // start 起点
  startOrigin = {
    x: 0,
    y: 50,
  };

  nodeStyle = {
    r: 25,
    color: "rgb(38, 186, 218)",
  };

  nodeBorder = {
    dr: 2,
    color: "#ffffff",
  };

  nodeShadow = {
    dr: 8,
    color: "transparent",
    // color: "rgba(255, 111, 187, 0.3)",
  };

  buttonGroupConfig = {
    dx: 0,
    dy: 0,
    // fill: "rgba(255, 111, 187, 0.3)",
    fill: "transparent",
    count: 2,
  };

  buttonBackground = {
    base: "#ffffff",
    hover: "#ddd",
    click: "#eee",
  };

  dotStyle = {
    r: 4,
    color: "rgb(38, 186, 218)",
  };

  bulletStyle = {
    r: 6,
    lineWidth: 1,
    stroke: "#4A70FF",
    fill: "rgba(25, 111, 187, 0.3)",
  };

  iconMaps = {
    copy: copyIcon,
    add: addIcon,
    delete: deleteIcon,
  };
  ICON_MAP = {
    [NODE_TYPE.REQUEST.type]: infoNodeIcon,
    [NODE_TYPE.API.type]: apiNodeIcon,
    [NODE_TYPE.ANSWER.type]: completeNodeIcon,
    [NODE_TYPE.START.type]: startNodeIcon,
  };

  defaultIcon = startNodeIcon;

  drawButton = ({ hoverGroup, x, y, name, iconImg = addIcon }) => {
    const button = hoverGroup.addShape("rect", {
      attrs: {
        x,
        y,
        width: this.buttonStyle.width,
        height: this.buttonStyle.height,
        radius: this.buttonStyle.radius,
        cursor: this.buttonStyle.cursor,
        fill: this.buttonBackground.base,
      },
      zIndex: 1060,
      name: `button:${name}`,
    });
    button.on("mouseenter", () => {
      button.attr({
        fill: this.buttonBackground.hover,
      });
    });
    button.on("mouseleave", () => {
      button.attr({
        fill: this.buttonBackground.base,
      });
    });
    button.on("click", () => {
      button.attr({
        fill: this.buttonBackground.click,
      });
    });

    const icon = hoverGroup.addShape("image", {
      attrs: {
        x,
        y,
        img: this.iconMaps[name],
        ...this.buttonStyle,
      },
      zIndex: 1070,
      name: `${name}-icon`,
      capture: false,
    });
    return { button, icon };
  };

  // 底部圆圈
  drawSourceBullet = ({ hoverGroup, originX, originY }) => {
    // 圆圈
    let x = originX;
    let y =
      originY + this.nodeStyle.r + this.nodeBorder.dr + this.nodeShadow.dr;

    // 热区
    const hotArea = hoverGroup.addShape("circle", {
      attrs: {
        x: x,
        y: y,
        r: this.bulletStyle.r,
        lineWidth: this.bulletStyle.lineWidth,
        stroke: this.bulletStyle.stroke,
        fill: this.bulletStyle.fill,
      },
      name: "source-hot-area",
      zIndex: 1300,
      capture: true,
      draggable: true,
    });

    hotArea.on("mouseenter", () => {
      hotArea.attr({
        fill: this.bulletStyle.fill,
      });
    });
    hotArea.on("mouseleave", () => {
      hotArea.attr({
        fill: "rgba(25, 111, 187, 0.5)",
      });
    });
  };

  /**
   * FLOW-DOC: 绘制 hover 态时的样式和新建, 删除,连线按钮
   */
  drawHover = ({ group, originX, originY }) => {
    // 创建一个包含 hover 内容的子组
    const hoverGroup = group.addGroup({ name: "hover-group", zIndex: 1000 });
    // 默认隐藏子组
    hoverGroup.hide();

    // 绘制连线起始点
    this.drawSourceBullet({ hoverGroup, originX, originY });

    // FLOW-DOC: 绘制右上角按钮区域
    // 从元素右上角往上 往右画
    // 先画底板

    // 向右偏移量
    const overlapMask = this.buttonGroupConfig.dx;
    const buttonGroupWidth =
      this.buttonStyle.width * this.buttonGroupConfig.count;
    const buttonGroupHeight = this.buttonStyle.height * 1;

    const dy = this.nodeStyle.r + this.buttonGroupConfig.dy + buttonGroupHeight;
    const dy2 =
      this.nodeStyle.r +
      this.nodeBorder.dr +
      this.nodeShadow.dr +
      this.bulletStyle.r;

    const dx = this.nodeStyle.r;
    hoverGroup.addShape("polygon", {
      attrs: {
        points: [
          // [横轴， 纵轴]
          [originX, originY - dy],
          // button 区域
          [originX + dx, originY - dy],
          [originX + dx + overlapMask + buttonGroupWidth, originY - dy],
          [
            originX + dx + overlapMask + buttonGroupWidth,
            originY - dy + buttonGroupHeight,
          ],
          [originX + dx, originY - dy + buttonGroupHeight],
          [originX + dx, originY + dy2],
          [originX, originY + dy2],
          [originX - this.bulletStyle.r, originY + dy2],
          [
            originX - this.bulletStyle.r,
            originY + dy2 - this.bulletStyle.r * 2,
          ],
          [originX, originY + dy2 - this.bulletStyle.r * 2],
          [originX, originY + dy2],
          [originX, originY - dy],
        ],
        fill: this.buttonGroupConfig.fill,
      },
      draggable: true,
      zIndex: 50,
      name: "nodeBase:node-hover-shape",
    });

    // button
    let buttonX = originX + dx + overlapMask;
    let buttonY = originY - dy;
    this.drawButton({
      hoverGroup,
      x: buttonX,
      y: buttonY,
      name: "copy",
    });

    buttonX = buttonX + this.buttonStyle.width;
    this.drawButton({
      hoverGroup,
      x: buttonX,
      y: buttonY,
      name: "delete",
    });
    buttonX = buttonX + this.buttonStyle.width;
    hoverGroup.sort();
  };

  /**
   * FLOW-DOC: 绘制选中样式
   */
  drawSelected = ({ group, originX: x, originY: y, nodeConfig }) => {};
  drawError = ({ group, originX: x, originY: y }) => {
    // 创建一个包含error内容的子组
    const errorGroup = group.addGroup({ name: "error-group" });
    errorGroup.hide(); // 默认隐藏子组

    errorGroup.addShape("image", {
      attrs: {
        x: x - 28 / 2,
        y: y - 12,
        img: errorIcon,
        width: 28,
        height: 28,
        cursor: "default",
      },
      draggable: true,
      name: "error",
      capture: false,
    });
  };
  drawNodeBase({ group, originX, originY, nodeData }) {
    const keyShape = group.addShape("circle", {
      attrs: {
        x: originX,
        y: originY,
        r: this.nodeStyle.r + this.nodeBorder.dr + this.nodeShadow.dr,
        fill: this.nodeShadow.color,
      },
      draggable: true,
      zIndex: 110,
    });

    group.addShape("circle", {
      attrs: {
        x: originX,
        y: originY,
        r: this.nodeStyle.r + this.nodeBorder.dr,
        fill: this.nodeBorder.color,
      },
      draggable: true,
      zIndex: 120,
    });
    // 绘制底层 node
    group.addShape("circle", {
      attrs: {
        x: originX,
        y: originY,
        r: this.nodeStyle.r,
        fill: this.nodeStyle.color,
        // anchors // 自定义属性，用来设置锚点
      },
      zIndex: 130,
      name: "nodeBase:node",
      draggable: true,
    });
    return keyShape;
  }

  drawNodeContent = ({
    group,
    originX,
    originY,
    nodeData: { NodeType, NodeName, data },
  }) => {
    const contentGroup = group.addGroup({
      id: "node-content",
      zIndex: 160,
    });

    contentGroup.addShape("image", {
      attrs: {
        x: originX - this.iconStyle.width / 2,
        y: originY - this.iconStyle.height / 2,
        img: this.ICON_MAP[NodeType] || this.defaultIcon,
        ...this.iconStyle,
      },
      capture: false,
    });
  };

  drawDot = ({ group, originX, originY }) => {
    // 绘制假装边的端点, 在元素下边缘中间
    group.addShape("circle", {
      attrs: {
        x: originX,
        y: originY + this.nodeStyle.r + this.nodeBorder.dr + this.nodeShadow.dr,
        r: this.dotStyle.r,
        fill: this.dotStyle.color,
      },
      zIndex: 200,
      name: "edge-source",
    });
  };
  // G6规定的节点生命周期函数
  draw(cfg, group) {
    console.log("cfg.nodeData", cfg, group);
    // 节点中心
    // const [originX, originY] = [this.startOrigin.x, this.startOrigin.y];
    const [originX, originY] = [0, 0];

    // 绘制节点基础
    // 三个个圆圈
    const keyShape = this.drawNodeBase({
      group,
      originX,
      originY,
      nodeData: cfg.nodeData,
    });

    // FLOW-DOC: 绘制节点内容
    // 里面内容, 其实只有一个图片
    this.drawNodeContent({
      group,
      originX,
      originY,
      nodeData: cfg.nodeData,
    });

    // FLOW-DOC: 绘制 hover 内容
    this.drawHover({ group, originX, originY, nodeData: cfg.nodeData });
    // FLOW-DOC: 绘制 选中 内容
    this.drawSelected({ group, originX, originY });
    this.drawError({ group, originX, originY });
    this.drawDot({ group, originX, originY });
    group.sort();
    return keyShape;
  }

  getAnchorPoints() {
    return [
      [0.5, 1], // 下侧中间
    ];
  }

  setState(name, value, item) {
    const group = item.getContainer();
    console.log("========= setState", name, value, item);

    if (name === "active") {
      const hoverGroup = group.find(
        (element) => element.get("name") === "hover-group"
      );
      // fix  当重新生成画布时可能存在hoverGroup为空的情况
      if (!hoverGroup) return;
      if (value) {
        hoverGroup.show();
      } else {
        hoverGroup.hide();
      }
    }
    if (name === "selected") {
      // 选中样式
      // const selectedGroup = group.find(
      //   (element) => element.get("name") === "selected-group"
      // );
      // if (value) {
      //   selectedGroup.show();
      // } else {
      //   selectedGroup.hide();
      // }
    } else if (name === "error") {
      const errorGroup = group.find(
        (element) => element.get("name") === "error-group"
      );

      if (value) {
        errorGroup.show();
      } else {
        errorGroup.hide();
      }
    } else if (name === "notAllowed") {
      // if (value) {
      //   nodeBase.attr({
      //     cursor: "not-allowed",
      //   });
      // } else {
      //   nodeBase.attr({
      //     cursor: "pointer",
      //   });
      // }
    }
  }
}

// 新建节点对象, 导出节点的生命周期函数
const startNode = new StartNode();
export default {
  draw: startNode.draw.bind(startNode),
  setState: startNode.setState.bind(startNode),
  getAnchorPoints: startNode.getAnchorPoints.bind(startNode),
};
