import G6 from "@antv/g6";
import infoNodeIcon from "@/assets/icons/info-node.svg";
import apiNodeIcon from "@/assets/icons/api-node.svg";
import completeNodeIcon from "@/assets/icons/complete-node.svg";
import startNodeIcon from "@/assets/icons/start-node.svg";
import addIcon from "@/assets/icons/copy-icon.svg";
import deleteIcon from "@/assets/icons/delete-icon.svg";
import errorIcon from "@/assets/icons/error-icon.svg";
import { NODE_TYPE } from "../qa-tree-node-list-config";
class NodeFactory {
  // 基础卡片的样式
  nodeStyle = {
    radius: 11,
    height: 48,
    width: 48,
    fill: "#1C66E5",
    lineWidth: 1,
    cursor: "pointer",
  };

  nodeBorder = {
    radius: 16,
    dh: 4,
    dw: 4,
    color: "#ffffff",
  };

  nodeShadow = {
    radius: 21,
    dh: 10,
    dw: 10,
    color: "transparent",
    // color: "rgba(255, 111, 187, 0.3)",
  };

  buttonGroupConfig = {
    dx: 2,
    dy: 0,
    // fill: "rgba(255, 111, 187, 0.3)",
    fill: "transparent",
    // 要放置几个按钮
    count: 2,
  };

  bulletStyle = {
    r: 6,
    lineWidth: 1,
    stroke: "#4A70FF",
    fill: "rgba(25, 111, 187, 0.3)",
  };

  activeShadowStyle = {
    shadowBlur: 12,
    shadowOffsetX: 0,
    shadowOffsetY: 6,
    shadowColor: "#12131914",
  };

  // 吸附态/选中态
  selectedbStyle = {
    stroke: "#4A70FF",
    fill: undefined,
  };

  contentStyle = {
    textMaxWidth: 140,
  };

  iconStyle = {
    width: 28,
    height: 28,
  };

  buttonStyle = {
    width: 20,
    height: 20,
    radius: 3,
    cursor: "pointer",
    // FLOW-DOC:: hover 按钮的间距
    // gap: 4,
    gap: 0,
  };

  buttonGroupStyle = {
    radius: 3,
    fill: "transparent",
    // fill: "#ff98",
  };

  buttonBackground = {
    base: "#ffffff",
    hover: "#ddd",
    click: "#eee",
  };

  nodePadding = {
    // 节点的padding
    top: 12,
    bottom: 12,
    left: 8,
    right: 12,
  };

  fontContent = {
    // 描述部分的文本样式
    fontSize: 12,
    fontWeight: 400,
    fontFamily: "PingFang SC",
    fontColor: "#010B3269",
    lineHeight: 16,
  };

  fontTitle = {
    // 标题的文本样式
    fontSize: 14,
    fontWeight: 500,
    fontFamily: "PingFang SC",
    fontColor: "#00010AED",
    lineHeight: 20,
    gap: 4,
  };

  ICON_MAP = {
    [NODE_TYPE.REQUEST.type]: infoNodeIcon,
    [NODE_TYPE.API.type]: apiNodeIcon,
    [NODE_TYPE.ANSWER.type]: completeNodeIcon,
    [NODE_TYPE.START.type]: startNodeIcon,
  };

  hotZoneStyle = {
    width: 16,
    height: 16,
    fill: "transparent",
  };

  hasSourceBullet = true;

  iconMaps = {
    // 可以是网络图片
    copy: "https://desk.qcloud.com/assets/setting_light-Cg6-bVTl.svg",
    add: addIcon,
    delete: deleteIcon,
  };

  drawNodeContent = ({
    group,
    originX,
    originY,
    nodeData: { NodeType, NodeName, data },
  }) => {
    const contentGroup = group.addGroup({
      id: "node-content",
      zIndex: 400,
    });

    contentGroup.addShape("image", {
      attrs: {
        x: -this.iconStyle.width / 2,
        y: -this.iconStyle.height / 2,
        img: this.ICON_MAP[NodeType] || this.defaultIcon,
        ...this.iconStyle,
      },
      zIndex: 400,
      capture: false,
    });
  };

  // 根据节点返回需要显示的具体信息
  getNodeContent = (
    type,
    {
      Request, // 询问节点的收集信息
      Response, // API节点的出参
      AnswerType, // 回复节点的答案
      InputAnswerData,
    }
  ) => {
    return `${1}`;
  };

  /**
   * FLOW-DOC: 绘制吸附态时的样式
   */
  drawSelected = ({ group, originX: x, originY: y, nodeConfig }) => {
    // 创建一个包含selected内容的子组
    // const selectedGroup = group.addGroup({ name: "selected-group" });
    // selectedGroup.hide(); // 默认隐藏子组
    // // 绘制边框, g6边框是居中的
    // const { lineWidth, width, height } = this.nodeStyle;
    // selectedGroup.addShape("rect", {
    //   attrs: {
    //     ...this.nodeStyle,
    //     ...this.selectedbStyle,
    //     ...this.activeShadowStyle,
    //     x: x + lineWidth / 2,
    //     y: y + lineWidth / 2,
    //     width: width - lineWidth,
    //     height: height - lineWidth,
    //   },
    //   capture: false,
    // });
  };

  /**
   * FLOW-DOC: 绘制 hover 态时的样式
   */
  drawHover = ({ group, nodeData: { NodeType } }) => {
    // 创建一个包含hover内容的子组
    // [0,0] 在元素的左上角
    let originX = 0;
    let originY = 0;
    const hoverGroup = group.addGroup({ name: "hover-group", zIndex: 1000 });
    // 默认隐藏子组
    hoverGroup.hide();

    this.drawSourceBullet({ hoverGroup, originX, originY });

    // FLOW-DOC:
    // 从元素右上角往上 往右画
    // 先画底板
    const overlapMask = this.buttonGroupConfig.dx;
    const buttonGroupWidth =
      this.buttonStyle.width * this.buttonGroupConfig.count;
    const buttonGroupHeight = this.buttonStyle.height * 1;

    const dy =
      this.nodeStyle.height / 2 + this.buttonGroupConfig.dy + buttonGroupHeight;
    const dy2 =
      this.nodeStyle.height / 2 +
      this.nodeBorder.dh +
      this.nodeShadow.dh +
      this.bulletStyle.r;
    const dx = this.nodeStyle.width / 2;

    hoverGroup.addShape("polygon", {
      attrs: {
        points: [
          // [横轴， 纵轴]
          [originX, originY - dy],
          // button 区域
          [originX + dx, originY - dy],
          [originX + dx + overlapMask + buttonGroupWidth, originY - dy],
          [
            originX + dx + overlapMask + buttonGroupWidth,
            originY - dy + buttonGroupHeight,
          ],
          [originX + dx, originY - dy + buttonGroupHeight],
          [originX + dx, originY + dy2],
          [originX, originY + dy2],
          [originX - this.bulletStyle.r, originY + dy2],
          [
            originX - this.bulletStyle.r,
            originY + dy2 - this.bulletStyle.r * 2,
          ],
          [originX, originY + dy2 - this.bulletStyle.r * 2],
          [originX, originY - dy],
        ],

        fill: this.buttonGroupConfig.fill,
      },
      draggable: true,
      zIndex: 50,
      name: "nodeBase:node-hover-shape",
    });

    // button 开始坐标
    let buttonX = originX + dx + overlapMask;
    let buttonY = originY - dy;
    console.log(NodeType);

    this.drawButton({
      hoverGroup,
      x: buttonX,
      y: buttonY,
      name: "copy",
    });
    buttonX = buttonX + this.buttonStyle.width;

    this.drawButton({
      hoverGroup,
      x: buttonX,
      y: buttonY,
      name: "delete",
    });
    buttonX = buttonX + this.buttonStyle.width;
    hoverGroup.sort();
    // deleteButton.toFront();
    // icon.toFront();
  };

  drawSourceBullet = ({ hoverGroup, originX, originY }) => {
    let x = originX;
    let y =
      originY +
      this.nodeStyle.height / 2 +
      this.nodeBorder.dh +
      this.nodeShadow.dh;

    const hotArea = hoverGroup.addShape("circle", {
      attrs: {
        x,
        y,
        r: this.bulletStyle.r,
        fill: this.bulletStyle.fill,
        stroke: this.bulletStyle.stroke,
        lineWidth: this.bulletStyle.lineWidth,
      },
      name: "source-hot-area",
      zIndex: 500,
      capture: true,
      draggable: true,
    });

    hotArea.on("mouseenter", () => {
      hotArea.attr({
        fill: this.bulletStyle.fill,
      });
    });
    hotArea.on("mouseleave", () => {
      hotArea.attr({
        fill: "rgba(25, 111, 187, 0.5)",
      });
    });
  };

  drawButton = ({ hoverGroup, x, y, name }) => {
    const button = hoverGroup.addShape("rect", {
      attrs: {
        x,
        y,
        width: this.buttonStyle.width,
        height: this.buttonStyle.height,
        radius: this.buttonStyle.radius,
        cursor: this.buttonStyle.cursor,
        fill: this.buttonBackground.base,
      },
      zIndex: 100,
      // FLOW-DOC:
      // button:delete
      name: `button:${name}`,
    });
    button.on("mouseenter", () => {
      button.attr({
        fill: this.buttonBackground.hover,
      });
    });
    button.on("mouseleave", () => {
      button.attr({
        fill: this.buttonBackground.base,
      });
    });
    button.on("click", () => {
      button.attr({
        fill: this.buttonBackground.click,
      });
    });

    const icon = hoverGroup.addShape("image", {
      attrs: {
        x,
        y,
        img: this.iconMaps[name],
        ...this.buttonStyle,
      },
      zIndex: 150,
      name: `${name}-icon`,
      capture: false,
    });

    return { button, icon };
  };

  /**
   * 绘制错误icon
   */
  drawError = ({ group, originX: x, originY: y }) => {
    // 创建一个包含error内容的子组
    const errorGroup = group.addGroup({ name: "error-group" });
    errorGroup.hide(); // 默认隐藏子组

    errorGroup.addShape("image", {
      attrs: {
        x: x - 28 / 2,
        y: y - 12,
        img: errorIcon,
        width: 28,
        height: 28,
        cursor: "default",
      },
      draggable: true,
      name: "error",
      capture: false,
    });
  };

  drawNodeBase({ group, originX, originY, nodeData }) {
    const nodeType = nodeData.NodeType;

    // 外扩张范围
    const keyShape = group.addShape("rect", {
      attrs: {
        x: originX - this.nodeShadow.dw - this.nodeBorder.dw,
        y: originY - this.nodeShadow.dh - this.nodeBorder.dh,
        radius: this.nodeShadow.radius,
        height:
          this.nodeStyle.height + 2 * (this.nodeShadow.dh + this.nodeBorder.dh),
        width:
          this.nodeStyle.width + 2 * (this.nodeShadow.dw + this.nodeBorder.dw),
        fill: this.nodeShadow.color,
      },
      draggable: true,
      zIndex: 110,
    });

    // 白色边框
    group.addShape("rect", {
      attrs: {
        x: originX - this.nodeBorder.dw,
        y: originY - this.nodeBorder.dh,
        radius: this.nodeBorder.radius,
        height: this.nodeStyle.height + 2 * this.nodeBorder.dh,
        width: this.nodeStyle.width + 2 * this.nodeBorder.dw,
        fill: this.nodeBorder.color,
      },
      draggable: true,
      zIndex: 120,
    });
    // 绘制底层node
    group.addShape("rect", {
      attrs: {
        x: originX,
        y: originY,
        radius: this.nodeStyle.radius,
        height: this.nodeStyle.height,
        width: this.nodeStyle.width,
        fill: this.nodeStyle.fill,
        lineWidth: this.nodeStyle.lineWidth,
      },
      zIndex: 130,
      name: "nodeBase:node",
      draggable: true,
    });

    return keyShape;
  }

  // G6规定的节点生命周期函数
  draw(cfg, group) {
    console.log("cfg.nodeData", cfg, group);
    // FLOW-DOC: 节点中心相对鼠标落点的位置
    // 把节点的 中心放在鼠标落点
    const [originX, originY] = [
      -this.nodeStyle.width / 2,
      -this.nodeStyle.height / 2,
    ];

    // 绘制节点基础, zIndex 从 100 到 399
    const keyShape = this.drawNodeBase({
      group,
      originX,
      originY,
      nodeData: cfg.nodeData,
    });

    // FLOW-DOC: 绘制节点内容 zIndex 从 400 到 999
    this.drawNodeContent({
      group,
      originX,
      originY,
      nodeData: cfg.nodeData,
    });

    // FLOW-DOC: zIndex 从 1000 到 1999
    this.drawHover({
      group,
      originX,
      originY,
      nodeData: cfg.nodeData,
    });

    // FLOW-DOC: zIndex 从 2000 到 2999
    this.drawError({ group, originX, originY });

    group.sort();
    return keyShape;
  }

  setState(name, value, item) {
    // selected 属性说明，点击第一次是选中，点击第二次是取消选中，这个行为是默认自带的。
    const group = item.getContainer();
    G6.Shape.Node.getShape("single-node").setState(name, value, item);
    // console.log(name, value, item);

    if (name === "active") {
      const hoverGroup = group.find(
        (element) => element.get("name") === "hover-group"
      );
      // fix  当重新生成画布时可能存在hoverGroup为空的情况
      if (!hoverGroup) return;
      if (value) {
        hoverGroup.show();
      } else {
        hoverGroup.hide();
      }
    }
    if (name === "selected") {
      //
    } else if (name === "error") {
      const errorGroup = group.find(
        (element) => element.get("name") === "error-group"
      );

      if (value) {
        errorGroup.show();
      } else {
        errorGroup.hide();
      }
    } else if (name === "notAllowed") {
      //
    }
  }
}

export default NodeFactory;
