/* eslint-disable @typescript-eslint/no-this-alias */
import _ from "lodash";

export default {
  getEvents() {
    return {
      "edge:dragstart": "onDragStart",
      // "node:dragenter": "onDragEnter",
      // "node:dragleave": "onDragLeave",
      drag: "updateEndPoint",
      "node:drop": "onDrop",
      "edge:dragend": "onDragEnd",
    };
  },
  shouldBegin({ target, item }) {
    const targetName = target.get("name");
    return (
      targetName === "end-arrow-hot-area" ||
      targetName === "start-arrow-hot-area"
    );
  },
  shouldEnd({ item }) {
    const self = this;

    const node = item.getModel();
    const sourceId = self.edge.getModel().source;
    // 终点不可以是开始节点, 不可以是自己
    if (node.type === "start-node" || node.id === sourceId) {
      return false;
    }
    // 是否有相同连线或者反方向连线
    // self.graph.getEdges()
    console.log(self.graph.getEdges(), self.graph.save().edges);
    const existing = self.graph.save().edges.find(({ source, target }) => {
      return (
        (source === sourceId && target === node.id) ||
        (source === node.id && target === sourceId)
      );
    });
    if (existing) {
      return false;
    }
    return true;
  },

  onDragStart(ev) {
    const self = this;
    if (self.key && !self.keydown) return;
    // 如果边的起点没有指定，则根据起点创建新边
    if (!self.shouldBegin(ev, self)) return;

    self.edge = ev.item;
    self.originalConfig = _.clone(ev.item.getModel());

    self.isStartArrow = ev.target.get("name") === "start-arrow";
    // 设置为updating状态, 这样两端的透明正方形不会跟着移动
    self.graph.setItemState(self.edge, "updating", true);
    // 暂时将该边的 capture 设置为 false，这样可以拾取到后面的元素
    self.edge.getKeyShape().set("capture", false);
  },
  onDragEnd(ev) {
    const self = this;
    if (self.key && !self.keydown) return;
    const { item } = ev;

    if (!item || !self.edge || item.getType() !== "node") {
      self.cancelUpdating({
        item: self.edge,
        x: ev.x,
        y: ev.y,
      });
    }
  },
  onDrop(ev) {
    const self = this;
    if (self.key && !self.keydown) return;
    const node = ev.item;
    const graph = self.graph;
    const model = node.getModel();

    // 如果起点已经指定而终点未指定，则指定终点
    if (self.edge) {
      if (!self.shouldEnd(ev, self)) return;

      const updateCfg = {
        source: self.isStartArrow ? model.id : self.edge.getModel().source,
        target: self.isStartArrow ? self.edge.getModel().target : model.id,
      };

      graph.emit("beforeupdateeedge", {});

      graph.updateItem(self.edge, updateCfg, false);

      graph.emit("afterUpdateEdge", {
        edge: self.edge,
      });

      // 暂时将该边的 capture 恢复为 true
      self.edge.getKeyShape().set("capture", true);
      self.graph.setItemState(self.edge, "updating", false);

      self.edge = null;
      self.isStartArrow = undefined;
      self.originalConfig = null;
    }
  },
  // 边的起点已经确定，边的末端跟随鼠标移动
  updateEndPoint(ev) {
    const self = this;
    if (self.key && !self.keydown) return;
    if (self.edge && self.edge.destroyed)
      self.cancelUpdating({ item: self.edge });
    const point = { x: ev.x, y: ev.y };

    // 若此时 另一端节点已经被移除，结束添加边
    if (
      !self.edge ||
      (!self.isStartArrow &&
        !self.graph.findById(self.edge.getModel().source)) ||
      (self.isStartArrow && !self.graph.findById(self.edge.getModel().target))
    ) {
      return;
    }
    if (self.edge) {
      // 更新边的终点为鼠标位置
      self.graph.updateItem(
        self.edge,
        {
          [self.isStartArrow ? "source" : "target"]: point,
        },
        false
      );
    }
  },
  // 恢复原来的边
  cancelUpdating(ev) {
    const self = this;
    if (self.key && !self.keydown) return;
    const graph = self.graph;
    const currentEdge = ev.item;

    if (self.edge === currentEdge || (ev.target && ev.target.isCanvas())) {
      if (self.edge) graph.updateItem(self.edge, self.originalConfig, false);
      self.edge = null;
      self.isStartArrow = undefined;
      self.originalConfig = null;
    }
  },
};
