<template>
  <div
    class="node"
    :draggable="true"
    @dragstart="
      (e) => {
        onDragStart(e, node);
      }
    "
  >
    <div ref="dragGhost" class="drag-ghost">
      <img
        :src="node.icon"
        :style="{
          backgroundColor: `${node.bgColor}`,
          color: `${node.iconColor}`,
        }"
      />
    </div>
    <img
      :class="[
        'node-icon',
        {
          radius: node.radius,
        },
      ]"
      :src="node.icon"
      :style="{
        backgroundColor: `${node.bgColor}`,
        color: `${node.iconColor}`,
      }"
    />
    <div>
      <div class="title">{{ node.name }}</div>
    </div>
  </div>
</template>

<script>
export default {
  name: "Node",
  components: {},
  props: {
    node: {
      type: Object,
      default: () => ({
        iconColor: "",
        description: "",
        name: "",
      }),
    },
  },
  methods: {
    onDragStart(e, node) {
      var img = new Image();
      img.src = node.icon;
      if (node.icon) {
        e.dataTransfer.setDragImage(this.$refs.dragGhost, 10, 10);
      }
      console.log(e, node);
      e.dataTransfer.setData("text/plain", this.node.type);
    },
  },
};
</script>

<style lang="less" scoped>
.node {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  position: relative;
  background: #ffffff;
  .drag-ghost {
    position: absolute;
    z-index: -1000;
  }
  .node-icon {
    height: 30px;
    width: 30px;
    padding: 10px;
    pointer-events: none;
    &.radius {
      border-radius: 100%;
    }
  }
  .title {
    pointer-events: none;
    font-size: 14px;
  }
}
</style>
